$fx = [];
$fx['sign_smime'] = base64_decode('');
$fx['sign_pem'] = base64_decode('');
$fx['sign_der_detached'] = base64_decode('');
$fx['enc_smime'] = base64_decode('');
$fx['enc_der'] = base64_decode('');
$dir = sys_get_temp_dir() . '/mc_cms_' . getmypid();
mkdir($dir);
$ca = "$dir/ca.pem";
file_put_contents($ca, $cert);
$in = "$dir/in.txt";
$message = "cms message\nline two\n";
file_put_contents($in, $message);
function path(string $n): string { global $dir; return "$dir/$n"; }
function put(string $n, string $c): string { file_put_contents(path($n), $c); return path($n); }

echo "constants ", OPENSSL_CMS_TEXT, ' ', OPENSSL_CMS_NOCERTS, ' ', OPENSSL_CMS_NOSIGS, ' ', OPENSSL_CMS_NOINTERN, ' ', OPENSSL_CMS_NOVERIFY, ' ',
    OPENSSL_CMS_DETACHED, ' ', OPENSSL_CMS_BINARY, ' ', OPENSSL_CMS_NOATTR, ' ', OPENSSL_CMS_OLDMIMETYPE, "\n";

// php-made fixtures
$out = path('out');
var_dump(openssl_cms_verify(put('a', $fx['sign_smime']), 0, null, [$ca], null, $out), file_get_contents($out) === $message);
var_dump(openssl_cms_verify(put('b', $fx['sign_pem']), 0, path('signers'), [$ca], null, $out, null, null, OPENSSL_ENCODING_PEM), trim(file_get_contents(path('signers'))) === trim($cert));
var_dump(openssl_cms_verify($in, OPENSSL_CMS_DETACHED, null, [$ca], null, $out, null, put('c', $fx['sign_der_detached']), OPENSSL_ENCODING_DER), file_get_contents($out) === $message);
file_put_contents(path('other'), "another message\n");
var_dump(openssl_cms_verify(path('other'), OPENSSL_CMS_DETACHED, null, [$ca], null, null, null, path('c'), OPENSSL_ENCODING_DER));
var_dump(openssl_cms_verify(path('a'), 0, null, []));
var_dump(openssl_cms_verify(path('a'), OPENSSL_CMS_NOVERIFY));
var_dump(openssl_cms_decrypt(put('d', $fx['enc_smime']), $out, $cert, $rsa), file_get_contents($out) === $message);
var_dump(openssl_cms_decrypt(put('e', $fx['enc_der']), $out, $cert, $rsa, OPENSSL_ENCODING_DER), file_get_contents($out) === $message);

// roundtrips in every encoding
foreach ([OPENSSL_ENCODING_SMIME => 'smime', OPENSSL_ENCODING_DER => 'der', OPENSSL_ENCODING_PEM => 'pem'] as $enc => $name) {
    foreach ([0, OPENSSL_CMS_BINARY | OPENSSL_CMS_NOATTR, OPENSSL_CMS_NOCERTS] as $fl) {
        $s = path("s_$name$fl");
        var_dump(openssl_cms_sign($in, $s, $cert, $rsa, null, $fl, $enc));
        $ok = openssl_cms_verify($s, ($fl & OPENSSL_CMS_NOCERTS) ? OPENSSL_CMS_NOINTERN : 0, null, [$ca], ($fl & OPENSSL_CMS_NOCERTS) ? $ca : null, $out, null, null, $enc);
        echo "$name $fl verify ", var_export($ok, true), ' ', var_export($ok ? file_get_contents($out) === $message : null, true), "\n";
    }
    $e = path("e_$name");
    var_dump(openssl_cms_encrypt($in, $e, [$cert], ['To' => 'x@y.z'], 0, $enc, OPENSSL_CIPHER_AES_192_CBC));
    var_dump(openssl_cms_decrypt($e, $out, $cert, $rsa, $enc), file_get_contents($out) === $message);
}
// detached DER / PEM with content
foreach ([OPENSSL_ENCODING_DER, OPENSSL_ENCODING_PEM] as $enc) {
    $s = path("det$enc");
    var_dump(openssl_cms_sign($in, $s, $cert, $rsa, null, OPENSSL_CMS_DETACHED, $enc));
    var_dump(openssl_cms_verify($in, OPENSSL_CMS_DETACHED, null, [$ca], null, null, null, $s, $enc));
    var_dump(openssl_cms_verify(path('other'), OPENSSL_CMS_DETACHED, null, [$ca], null, null, null, $s, $enc));
}
var_dump(str_starts_with(file_get_contents(path('e_smime')), "To: x@y.z\nMIME-Version: 1.0\n"), str_starts_with(file_get_contents(path('s_pem0')), '-----BEGIN CMS-----'));
// php's output-file side effects: $pk7 is created empty and only receives the PEM when a
// signers file is requested too; $content is filled even by a failed verification.
function sizes(): string {
    $o = [];
    foreach (['sg', 'ct', 'pk'] as $n) { $o[] = $n . '=' . (is_file(path($n)) ? filesize(path($n)) > 0 ? 'data' : 'empty' : '-'); }
    return implode(' ', $o);
}
function clean(): void { foreach (['sg', 'ct', 'pk'] as $n) { if (is_file(path($n))) { unlink(path($n)); } } }
foreach ([[null, null], ['sg', null], [null, 'pk'], ['sg', 'pk']] as [$sg, $pk]) {
    clean();
    $r = openssl_cms_verify(path('a'), 0, $sg ? path($sg) : null, [$ca], null, path('ct'), $pk ? path($pk) : null);
    echo json_encode($r), ' ', sizes(), "\n";
}
openssl_cms_sign($in, path('der'), $cert, $rsa, null, OPENSSL_CMS_BINARY, OPENSSL_ENCODING_DER);
$b = file_get_contents(path('der'));
$b[strpos($b, 'c')] = 'X';
file_put_contents(path('derbad'), $b);
clean();
$r = openssl_cms_verify(path('derbad'), 0, path('sg'), [$ca], null, path('ct'), path('pk'), null, OPENSSL_ENCODING_DER);
echo json_encode($r), ' ', sizes(), "\n";
file_put_contents(path('junkder'), 'junk');
clean();
$r = openssl_cms_verify(path('junkder'), 0, path('sg'), [$ca], null, path('ct'), path('pk'), null, OPENSSL_ENCODING_DER);
echo json_encode($r), ' ', sizes(), "\n";
array_map('unlink', glob("$dir/*"));
rmdir($dir);
